149	    /**
150	     * Normalize an email to its canonical stored form, which is lower-cased. This is the single
151	     * source of truth for how an email is persisted, so inputs that differ only in letter case
152	     * are stored identically. Applied by {@link #setEmail(String)} so every persistence path
153	     * (create and update, mapper or hand-copied) stores the same canonical value.
154	     *
155	     * @param email the raw email, possibly {@code null}
156	     * @return the lower-cased form, or {@code null} if the input was {@code null}
157	     */
158	    public static String normalizeEmail(String email) {
159	        return email == null ? null : email.toLowerCase();
160	    }
161	
162	    /**
163	     * Normalize a telephone to its canonical E.164 stored form. This is the single source of
164	     * truth for how a telephone is compared and persisted, so inputs that differ only in
165	     * formatting (spaces, dashes, brackets) are treated as the same number.
166	     *
167	     * <p>The rules are:
168	     * <ul>
169	     *   <li>spaces, dashes and brackets are stripped;</li>
170	     *   <li>a leading {@code '+'} and its country code are kept as given;</li>
171	     *   <li>otherwise country code {@code '+61'} is assumed and a single leading {@code '0'}
172	     *       is dropped from the national digits;</li>
173	     *   <li>the result must have 8 to 15 digits after the {@code '+'};</li>
174	     *   <li>for a recognized country code the national number (the digits after the country
175	     *       code) must have the length that code requires: {@code '+61'} requires 9 national
176	     *       digits and {@code '+1'} requires 10.</li>
177	     * </ul>
178	     * For example {@code "0412 345 678"} becomes {@code "+61412345678"}. Already-normalized
179	     * values are returned unchanged.
180	     *
181	     * @param telephone the raw telephone, possibly {@code null}
182	     * @return the E.164 form, or {@code null} if the input is {@code null} or cannot form a
183	     *     valid E.164 number
184	     */
185	    public static String normalizeTelephone(String telephone) {
186	        if (telephone == null) {
187	            return null;
188	        }
189	        String trimmed = telephone.trim();
190	        boolean hasCountryCode = trimmed.startsWith("+");
191	        // Strip spaces, dashes and brackets; a leading '+' (if any) is left in place.
192	        String stripped = trimmed.replaceAll("[\\s\\-()]", "");
193	        if (hasCountryCode) {
194	            stripped = stripped.substring(1);
195	        }
196	        if (!stripped.matches("\\d+")) {
197	            return null;
198	        }
199	        String digits;
200	        if (hasCountryCode) {
201	            digits = stripped;
202	        } else {
203	            if (stripped.startsWith("0")) {
204	                stripped = stripped.substring(1);
205	            }
206	            digits = "61" + stripped;
207	        }
208	        if (digits.length() < 8 || digits.length() > 15) {
209	            return null;
210	        }
211	        if (!hasValidNationalNumberLength(digits)) {
212	            return null;
213	        }
214	        return "+" + digits;
215	    }
216	
217	    /**
218	     * Required national-number length (the count of digits after the country code) for each
219	     * recognized country code, longest country code first so the prefix match is unambiguous.
220	     */
221	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS = new LinkedHashMap<>();
222	    static {
223	        NATIONAL_NUMBER_LENGTHS.put("61", 9);
224	        NATIONAL_NUMBER_LENGTHS.put("1", 10);
225	    }
226	
227	    /**
228	     * Check that the national number of an E.164 digit string (no leading {@code '+'}) has the
229	     * length its country code requires. A country code with no registered length places no
230	     * additional constraint and is accepted.
231	     *
232	     * @param digits the E.164 digits without the leading {@code '+'}
233	     * @return {@code true} if the national-number length is valid for the country code
234	     */
235	    private static boolean hasValidNationalNumberLength(String digits) {
236	        for (Map.Entry<String, Integer> entry : NATIONAL_NUMBER_LENGTHS.entrySet()) {
237	            String countryCode = entry.getKey();
238	            if (digits.startsWith(countryCode)) {
239	                return digits.length() - countryCode.length() == entry.getValue();
240	            }
241	        }
242	        return true;
243	    }
244	
245	    /**
246	     * Common street-type abbreviations expanded by {@link #normalizeAddress(String)}, keyed by the
247	     * upper-cased abbreviation.
248	     */
249	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
250	        "ST", "STREET",
251	        "RD", "ROAD",
252	        "AVE", "AVENUE");
253	
254	    /**
255	     * Normalize an address to its canonical stored form. Leading and trailing whitespace is
256	     * trimmed, internal runs of whitespace are collapsed to a single space, the text is upper-cased,
257	     * and common street-type abbreviations are expanded as whole words ({@code ST}->{@code STREET},
258	     * {@code RD}->{@code ROAD}, {@code AVE}->{@code AVENUE}). This is the single source of truth for
259	     * how an address is persisted and compared, so inputs that differ only in letter case, spacing
260	     * or abbreviation are treated as the same address. Applied by {@link #setAddress(String)} so
261	     * every persistence path (create and update, mapper or hand-copied) stores the same canonical
262	     * value. The transform is idempotent: a normalized address normalizes to itself.
263	     *
264	     * @param address the raw address, possibly {@code null}
265	     * @return the normalized form, or {@code null} if the input was {@code null}
266	     */
267	    public static String normalizeAddress(String address) {
268	        if (address == null) {
269	            return null;
270	        }
271	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase();
272	        if (collapsed.isEmpty()) {
273	            return collapsed;
274	        }
275	        String[] tokens = collapsed.split(" ");
276	        StringBuilder normalized = new StringBuilder(collapsed.length());
277	        for (int i = 0; i < tokens.length; i++) {
278	            if (i > 0) {
279	                normalized.append(' ');
280	            }
281	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
282	        }
283	        return normalized.toString();
284	    }
285	
286	    /**
287	     * Normalize a household field (such as last name or address) to its canonical form for
288	     * duplicate-household comparison. Leading and trailing whitespace is trimmed, internal runs
289	     * of whitespace are collapsed to a single space, and the result is lower-cased, so inputs
290	     * that differ only in letter case or spacing are treated as the same value.
291	     *
292	     * @param value the raw field value, possibly {@code null}
293	     * @return the normalized form, or {@code null} if the input was {@code null}
294	     */
295	    public static String normalizeHousehold(String value) {
296	        if (value == null) {
297	            return null;
298	        }
299	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
300	    }
301	
302	    /**
303	     * Compute the stable identifier shared by all owners in the same household, i.e. with the same
304	     * last name (compared case-insensitively with collapsed whitespace, see
305	     * {@link #normalizeHousehold(String)}) and the same normalized address (see
306	     * {@link #normalizeAddress(String)}). The value is deterministic in those two fields, so two
307	     * owners who share a household are assigned the same id. It is formatted {@code 'HH-<HEX12>'}
308	     * where {@code HEX12} is the first twelve upper-cased hex characters of the SHA-256 digest of
309	     * the normalized last name and address.
310	     *
311	     * @param lastName the owner's last name, possibly {@code null}
312	     * @param address the owner's address, possibly {@code null}
313	     * @return the household id, or {@code null} if either field is {@code null}
314	     */
315	    public static String householdId(String lastName, String address) {
316	        String normalizedLastName = normalizeHousehold(lastName);
317	        String normalizedAddress = normalizeAddress(address);
318	        if (normalizedLastName == null || normalizedAddress == null) {
319	            return null;
320	        }
321	        String key = normalizedLastName + "\n" + normalizedAddress;
322	        return "HH-" + sha256Hex(key).substring(0, 12).toUpperCase();
323	    }
324	
325	    /**
326	     * Compute the full lower-case hex SHA-256 digest of the UTF-8 bytes of {@code value}. This is the
327	     * shared primitive behind every hash-derived owner value (the household id and the customer code),
328	     * so they all agree on algorithm and encoding.
329	     *
330	     * @param value the string to digest, never {@code null}
331	     * @return the 64-character lower-case hex digest
332	     */
333	    private static String sha256Hex(String value) {
334	        try {
335	            byte[] digest = MessageDigest.getInstance("SHA-256")
336	                .digest(value.getBytes(StandardCharsets.UTF_8));
337	            StringBuilder hex = new StringBuilder(digest.length * 2);
338	            for (byte b : digest) {
339	                hex.append(String.format("%02x", b));
340	            }
341	            return hex.toString();
342	        } catch (NoSuchAlgorithmException e) {
343	            // SHA-256 is a standard algorithm required to be present on every JVM.
344	            throw new IllegalStateException("SHA-256 not available", e);
345	        }
346	    }
347	
348	    /**
349	     * Build an owner's {@code customerCode}, the stable owner identity assigned once when the owner is
350	     * created. It is formatted {@code '<REGION>-<HASH8>'} where:
351	     * <ul>
352	     *   <li>{@code REGION} is the region code derived from the postcode (see
353	     *       {@link #regionForPostcode(String)}), or {@code 'UNKNOWN'} when the postcode is absent or
354	     *       in no known range, and</li>
355	     *   <li>{@code HASH8} is the first eight upper-cased hex characters of the SHA-256 digest of the
356	     *       normalized telephone (see {@link #normalizeTelephone(String)}) concatenated with the last
357	     *       name.</li>
358	     * </ul>
359	     * The value is deterministic in the postcode, telephone and last name (e.g.
360	     * {@code 'NSW-1A2B3C4D'}); it carries no sequence number.
361	     *
362	     * @param postcode the owner's postcode, possibly {@code null}
363	     * @param telephone the owner's raw telephone, possibly {@code null}
364	     * @param lastName the owner's last name, possibly {@code null}
365	     * @return the customer code, or {@code null} if the telephone or last name is {@code null}
366	     */
367	    public static String customerCode(String postcode, String telephone, String lastName) {
368	        if (telephone == null || lastName == null) {
369	            return null;
370	        }
371	        String region = regionForPostcode(postcode);
372	        if (region == null) {
373	            region = "UNKNOWN";
374	        }
375	        String normalizedTelephone = normalizeTelephone(telephone);
376	        String key = (normalizedTelephone == null ? "" : normalizedTelephone) + lastName;
377	        return region + "-" + sha256Hex(key).substring(0, 8).toUpperCase();
378	    }
379	
380	    /**
381	     * Compute an owner's {@code identityKey}, the single derived value through which all
382	     * duplicate detection is now expressed. It consolidates the three formerly separate
383	     * telephone, email and household duplicate checks into one key, formatted as
384	     * {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}:
385	     * <ul>
386	     *   <li>the normalized telephone (see {@link #normalizeTelephone(String)}),</li>
387	     *   <li>the normalized email (see {@link #normalizeEmail(String)}), or the empty string
388	     *       when no email is present, and</li>
389	     *   <li>the household id (see {@link #householdId(String, String)}).</li>
390	     * </ul>
391	     * A {@code null} component is rendered as the empty string. Two owners are the same identity
392	     * only when their <em>whole</em> keys are equal; because the telephone is part of the key, two
393	     * members of the same household with different telephones have different keys.
394	     *
395	     * @param telephone the owner's raw telephone, possibly {@code null}
396	     * @param email the owner's email, possibly {@code null}
397	     * @param lastName the owner's last name, possibly {@code null}
398	     * @param address the owner's address, possibly {@code null}
399	     * @return the identity key, never {@code null}
400	     */
401	    public static String identityKey(String telephone, String email, String lastName, String address) {
402	        String normalizedTelephone = normalizeTelephone(telephone);
403	        String normalizedEmail = normalizeEmail(email);
404	        String household = householdId(lastName, address);
405	        return (normalizedTelephone == null ? "" : normalizedTelephone)
406	            + "|" + (normalizedEmail == null ? "" : normalizedEmail)
407	            + "|" + (household == null ? "" : household);
408	    }
409	
410	    /**
411	     * Build an owner's {@code membershipNumber}, the stable membership identifier derived from the
412	     * owner's own persisted fields. It is formatted {@code '<customerCode>-M<YY>'} where {@code YY}
413	     * is the last two digits of the registration date's year (e.g. {@code 'NSW-1A2B3C4D-M26'}). The
414	     * value is deterministic in those two fields.
415	     *
416	     * @param customerCode the owner's customer code, possibly {@code null}
417	     * @param registrationDate the owner's registration date, possibly {@code null}
418	     * @return the membership number, or {@code null} if either field is {@code null}
419	     */
420	    public static String membershipNumber(String customerCode, LocalDate registrationDate) {
421	        if (customerCode == null || registrationDate == null) {
422	            return null;
423	        }
424	        return String.format("%s-M%02d", customerCode, registrationDate.getYear() % 100);
425	    }
426	
427	    /**
428	     * Build an owner's {@code membershipLevel}, the derived numeric level assigned on create. The
429	     * value starts at 1, gains 1 when an email is present and gains 1 when {@code namesakeCount} is 0,
430	     * and is capped at 3 (level 4 is reserved for tenure). The value is deterministic in those two
431	     * fields.
432	     *
433	     * @param namesakeCount the owner's namesake count, possibly {@code null}
434	     * @param email the owner's email, possibly {@code null}
435	     * @return the membership level, an integer from 1 to 3
436	     */
437	    public static int membershipLevel(Integer namesakeCount, String email) {
438	        int level = 1;
439	        if (email != null && !email.isEmpty()) {
440	            level++;
441	        }
442	        if (namesakeCount != null && namesakeCount == 0) {
443	            level++;
444	        }
445	        return Math.min(level, 3);
446	    }
447	
448	    /**
449	     * Fixed city-to-region table used by {@link #regionForCity(String)} to resolve a city's region
450	     * for postcode validation, keyed by the exact city name.
451	     */
452	    private static final Map<String, String> CITY_REGION = Map.of(
453	        "Sydney", "NSW",
454	        "Melbourne", "VIC",
455	        "Brisbane", "QLD");
456	
457	    /**
458	     * Derive an owner's {@code locality}, the canonical region for the owner, from the {@code REGION}
459	     * segment of the owner's {@code customerCode} (see {@link #customerCode(String, String, String)}).
460	     * Because the customer code's region is itself derived from the postcode, the locality now shares
461	     * the owner's region-and-hash identity: it is the text before the first {@code '-'} of the customer
462	     * code. When the owner has no customer code the locality is {@code 'UNKNOWN'}.
463	     *
464	     * @param customerCode the owner's customer code, possibly {@code null}
465	     * @return the canonical region string, or {@code 'UNKNOWN'} when no customer code is present
466	     */
467	    public static String locality(String customerCode) {
468	        if (customerCode == null) {
469	            return "UNKNOWN";
470	        }
471	        int dash = customerCode.indexOf('-');
472	        return dash < 0 ? customerCode : customerCode.substring(0, dash);
473	    }
474	
475	    /**
476	     * Resolve the canonical region for a city from the fixed {@link #CITY_REGION} table. A city not
477	     * in the table (including {@code null}) resolves to {@code 'UNKNOWN'}.
478	     *
479	     * @param city the owner's city, possibly {@code null}
480	     * @return the matching region, or {@code 'UNKNOWN'} when the city is not in the table
481	     */
482	    private static String regionForCity(String city) {
483	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
484	    }
485	
486	    /**
487	     * Fixed region-to-postcode-range table used by {@link #isPostcodeValidForCity(String, String)}
488	     * and {@link #regionForPostcode(String)}, keyed by the canonical region. Each entry is the
489	     * inclusive low and high bound of the region's valid 4-digit postcodes
490	     * ({@code NSW} 2000-2099, {@code VIC} 3000-3099, {@code QLD} 4000-4099). A region not in this
491	     * table (including {@code 'UNKNOWN'}) places no range constraint.
492	     */
493	    private static final Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
494	        "NSW", new int[] {2000, 2099},
495	        "VIC", new int[] {3000, 3099},
496	        "QLD", new int[] {4000, 4099});
497	
498	    /**
499	     * Resolve the canonical region whose postcode range contains the given postcode, using the fixed
500	     * {@link #REGION_POSTCODE_RANGES} table. A {@code null} postcode, one that is not exactly four
501	     * digits, or one that falls in no known range resolves to {@code null}.
502	     *
503	     * @param postcode the owner's postcode, possibly {@code null}
504	     * @return the matching region, or {@code null} when no range contains the postcode
505	     */
506	    private static String regionForPostcode(String postcode) {
507	        if (postcode == null || !postcode.matches("\\d{4}")) {
508	            return null;
509	        }
510	        int value = Integer.parseInt(postcode);
511	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGES.entrySet()) {
512	            int[] range = entry.getValue();
513	            if (value >= range[0] && value <= range[1]) {
514	                return entry.getKey();
515	            }
516	        }
517	        return null;
518	    }
519	
520	    /**
521	     * Check whether a postcode is valid for an owner's city. Postcode is optional, so a
522	     * {@code null} or empty postcode is always valid. When present it must be exactly four
523	     * digits, and when the city's region (from the fixed city-to-region table) has a known postcode
524	     * range the value must fall within that inclusive range. A city with no known region accepts
525	     * any four-digit postcode. This is the single source of
526	     * truth for postcode validity, shared by the DTO validation and any persistence path.
527	     *
528	     * @param postcode the owner's postcode, possibly {@code null}
529	     * @param city the owner's city, possibly {@code null}
530	     * @return {@code true} if the postcode is absent or valid for the city, {@code false} otherwise
531	     */
532	    public static boolean isPostcodeValidForCity(String postcode, String city) {
533	        if (postcode == null || postcode.isEmpty()) {
534	            return true;
535	        }
536	        if (!postcode.matches("\\d{4}")) {
537	            return false;
538	        }
539	        int[] range = REGION_POSTCODE_RANGES.get(regionForCity(city));
540	        if (range == null) {
541	            return true;
542	        }
543	        int value = Integer.parseInt(postcode);
544	        return value >= range[0] && value <= range[1];
545	    }
546	
547	    /**
548	     * Compute an owner's {@code checkDigit}, a single Luhn check digit (0-9) over the digits
549	     * contained in the {@code customerCode}. Non-digit characters in the code are ignored. The
550	     * value is deterministic in the customer code and is the standard Luhn check digit: each
551	     * digit is weighted right-to-left, every second digit (starting with the rightmost) is
552	     * doubled with digit sums above nine reduced by nine, and the check digit is the amount that
553	     * brings the weighted sum up to the next multiple of ten.
554	     *
555	     * @param customerCode the owner's customer code, possibly {@code null}
556	     * @return the Luhn check digit from 0 to 9, or {@code null} if the customer code is {@code null}
557	     */
558	    public static Integer checkDigit(String customerCode) {
559	        if (customerCode == null) {
560	            return null;
561	        }
562	        int sum = 0;
563	        boolean dbl = true;
564	        for (int i = customerCode.length() - 1; i >= 0; i--) {
565	            char c = customerCode.charAt(i);
566	            if (c < '0' || c > '9') {
567	                continue;
568	            }
569	            int d = c - '0';
570	            if (dbl) {
571	                d *= 2;
572	                if (d > 9) {
573	                    d -= 9;
574	                }
575	            }
576	            sum += d;
577	            dbl = !dbl;
578	        }
579	        return (10 - (sum % 10)) % 10;
580	    }
581	
582	    /**
583	     * Derive an owner's {@code contactPreference}, the preferred channel for contacting the owner.
584	     * The value is {@code 'EMAIL'} when an email is present and {@code 'PHONE'} otherwise. The value
585	     * is deterministic in the email.
586	     *
587	     * @param email the owner's email, possibly {@code null}
588	     * @return {@code 'EMAIL'} when an email is present, otherwise {@code 'PHONE'}
589	     */
590	    public static String contactPreference(String email) {
591	        return (email != null && !email.isEmpty()) ? "EMAIL" : "PHONE";
592	    }
593	
594	    protected Set<Pet> getPetsInternal() {
595	        if (this.pets == null) {
596	            this.pets = new HashSet<>();
597	        }
598	        return this.pets;
599	    }
600	
601	    protected void setPetsInternal(Set<Pet> pets) {
602	        this.pets = pets;
603	    }
604	
605	    public List<Pet> getPets() {
606	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
607	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
608	        return Collections.unmodifiableList(sortedPets);
609	    }
610	
611	    public void setPets(List<Pet> pets) {
612	        this.pets = new HashSet<>(pets);
613	    }
614	
615	    public void addPet(Pet pet) {
616	        getPetsInternal().add(pet);
617	        pet.setOwner(this);
618	    }
619	
620	    /**
621	     * Return the Pet with the given name, or null if none found for this Owner.
622	     *
623	     * @param name to test
624	     * @return true if pet name is already in use
625	     */
626	    public Pet getPet(String name) {
627	        return getPet(name, false);
628	    }
629	
630	    /**
631	     * Return the Pet with the given name, or null if none found for this Owner.
632	     *
633	     * @param name to test
634	     * @return true if pet name is already in use
635	     */
636	    public Pet getPet(String name, boolean ignoreNew) {
637	        name = name.toLowerCase();
638	        for (Pet pet : getPetsInternal()) {
639	            if (!ignoreNew || !pet.isNew()) {
640	                String compName = pet.getName();
641	                compName = compName.toLowerCase();
642	                if (compName.equals(name)) {
643	                    return pet;
644	                }
645	            }
646	        }
647	        return null;
648	    }
649	
650	    public Pet getPet(Integer petId) {
651	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
652	    }
653	
654	    @Override
655	    public String toString() {
656	        return new ToStringCreator(this)
657	
658	            .append("id", this.getId())
659	            .append("new", this.isNew())
660	            .append("lastName", this.getLastName())
661	            .append("firstName", this.getFirstName())
662	            .append("address", this.address)
663	            .append("city", this.city)
664	            .append("telephone", this.telephone)
665	            .toString();
666	    }
667	}
